#include "PluginProcessor.h"
#include "FactoryPresets.h"
namespace {
juce::String family(int engine) {return juce::StringArray{"FM","Phase","String","Sampler","Drum synth","Drum kit"}[std::clamp(engine,0,5)];}
}
std::vector<SoundInfo> PocketProcessor::soundCatalog() const {
    std::vector<SoundInfo> result;
    for(size_t i=0;i<pocket::factoryPresets.size();++i){const auto& p=pocket::factoryPresets[i];SoundInfo s;s.id="factory:"+juce::String(int(i));s.factory=int(i);s.engine=p.engine;s.name=juce::String(p.name).fromFirstOccurrenceOf(" / ",false,false);s.bank="Factory";s.category=family(p.engine);s.sample=p.engine==3;s.kit=p.engine==5;s.variant=p.engine==5?"Kit":"Original";const char* waves[]={"VelvetKeys.wav","GlassMallet.wav","AirChoir.wav","LowPluck.wav"};s.source=s.sample?waves[p.sample]:s.kit?s.name+" / 8 WAVs":"Built in";result.push_back(std::move(s));}
    for(size_t i=0;i<userPresets.size();++i){const auto& p=userPresets[i];SoundInfo s;s.id=p.id;s.user=int(i);s.bank=p.bank;s.name=p.name.startsWith("KIT / ")?p.name.substring(6):p.name;s.engine=p.isKit?5:3;s.category=family(s.engine);s.kit=p.isKit;s.sample=!p.isKit;s.source=p.source;s.root=float(p.parameters.getProperty("sampleRoot",60));if(!p.isKit&&s.name.contains(" / ")){s.variant=s.name.fromLastOccurrenceOf(" / ",false,false);s.name=s.name.upToLastOccurrenceOf(" / ",false,false);}else s.variant=p.isKit?"Kit":"Original";result.push_back(std::move(s));}
    std::stable_sort(result.begin(),result.end(),[](const auto& a,const auto& b){return (a.name+" "+a.variant).compareNatural(b.name+" "+b.variant)<0;});return result;
}
bool PocketProcessor::loadSound(const juce::String& id,juce::String& error) {for(const auto& s:soundCatalog())if(s.id==id){if(s.factory>=0){applyPreset(s.factory);return true;}return applyUserPreset(s.user,error);}error="This sound is not installed. Import its bank again.";return false;}
void PocketProcessor::setSelectedSound(const juce::String& id){const juce::ScopedLock lock(libraryStateLock);selectedSoundId=id;if(id.isNotEmpty()){if(state.getRawParameterValue("engine")->load()>=4)lastDrumSound=id;else lastSynthSound=id;}}
juce::String PocketProcessor::selectedSound() const {const juce::ScopedLock lock(libraryStateLock);return selectedSoundId;}
juce::String PocketProcessor::lastSound(bool drums) const {const juce::ScopedLock lock(libraryStateLock);return drums?lastDrumSound:lastSynthSound;}
bool PocketProcessor::isFavorite(const juce::String& id) const {const juce::ScopedLock lock(libraryStateLock);return favorites.contains(id);}
void PocketProcessor::toggleFavorite(const juce::String& id){if(id.isEmpty())return;const juce::ScopedLock lock(libraryStateLock);if(favorites.contains(id))favorites.removeString(id);else if(favorites.size()<256)favorites.add(id);}
void PocketProcessor::initializeSoundSlots(){const int synth[]={0,1,2,3,6,7,18,19},drums[]={22,23,24,4,5,22,23,24};for(int i=0;i<8;++i){soundSlotIds[0][size_t(i)]="factory:"+juce::String(synth[i]);soundSlotIds[1][size_t(i)]="factory:"+juce::String(drums[i]);}}
bool PocketProcessor::assignSoundSlot(bool drums,int slot){if(slot<0||slot>7)return false;const juce::ScopedLock lock(libraryStateLock);if(selectedSoundId.isEmpty())return false;soundSlotIds[size_t(drums)][size_t(slot)]=selectedSoundId;juce::ValueTree settings("Settings");for(const auto& child:state.copyState()){const auto id=child.getProperty("id").toString();if(child.hasType("PARAM")&&!id.startsWith("tape")&&!id.startsWith("track")&&id!="tempo"&&id!="volume"&&!id.startsWith("seq")&&!id.startsWith("arp")&&id!="metronome"&&!id.startsWith("input")&&!id.startsWith("eq")&&!id.startsWith("master")&&id!="clickVolume")settings.addChild(child.createCopy(),-1,nullptr);}slotSettings[size_t(drums)][size_t(slot)]=settings;return true;}
juce::String PocketProcessor::soundSlot(bool drums,int slot) const {if(slot<0||slot>7)return {};const juce::ScopedLock lock(libraryStateLock);return soundSlotIds[size_t(drums)][size_t(slot)];}
bool PocketProcessor::recallSoundSlot(bool drums,int slot,juce::String& error){if(slot<0||slot>7)return false;juce::ValueTree settings;{const juce::ScopedLock lock(libraryStateLock);settings=slotSettings[size_t(drums)][size_t(slot)].createCopy();}if(!loadSound(soundSlot(drums,slot),error))return false;for(const auto& child:settings){auto* p=state.getParameter(child.getProperty("id").toString());if(p)p->setValueNotifyingHost(p->convertTo0to1(float(child.getProperty("value"))));}return true;}
juce::ValueTree PocketProcessor::librarySnapshot() const {const juce::ScopedLock lock(libraryStateLock);juce::ValueTree tree("SoundLibrary");tree.setProperty("selected",selectedSoundId,nullptr);tree.setProperty("lastSynth",lastSynthSound,nullptr);tree.setProperty("lastDrum",lastDrumSound,nullptr);for(const auto& id:favorites){juce::ValueTree item("Favorite");item.setProperty("id",id,nullptr);tree.addChild(item,-1,nullptr);}for(int mode=0;mode<2;++mode)for(int i=0;i<8;++i){juce::ValueTree slot("Slot");slot.setProperty("mode",mode,nullptr);slot.setProperty("slot",i,nullptr);slot.setProperty("id",soundSlotIds[size_t(mode)][size_t(i)],nullptr);if(slotSettings[size_t(mode)][size_t(i)].isValid())slot.addChild(slotSettings[size_t(mode)][size_t(i)].createCopy(),-1,nullptr);tree.addChild(slot,-1,nullptr);}return tree;}
void PocketProcessor::restoreLibrary(const juce::ValueTree& tree){const juce::ScopedLock lock(libraryStateLock);initializeSoundSlots();slotSettings={};favorites.clear();selectedSoundId=tree.getProperty("selected").toString().substring(0,512);lastSynthSound=tree.getProperty("lastSynth","factory:0").toString().substring(0,512);lastDrumSound=tree.getProperty("lastDrum","factory:22").toString().substring(0,512);for(const auto& child:tree){const auto id=child.getProperty("id").toString().substring(0,512);if(child.hasType("Favorite")&&favorites.size()<256)favorites.addIfNotAlreadyThere(id);if(child.hasType("Slot")){int mode=int(child.getProperty("mode",-1)),slot=int(child.getProperty("slot",-1));if(mode>=0&&mode<2&&slot>=0&&slot<8){soundSlotIds[size_t(mode)][size_t(slot)]=id;slotSettings[size_t(mode)][size_t(slot)]=child.getChildWithName("Settings").createCopy();}}}}
bool PocketProcessor::importSamples(const juce::Array<juce::File>& files,juce::String& error){if(files.isEmpty())return false;juce::ZipFile::Builder zip;juce::Array<juce::var> presets;for(const auto& file:files){if(file.getSize()>16000000){error="Each imported audio file must be smaller than 16 MB.";return false;}auto sample=readSample(file,error);if(sample.frames.empty())return false;uint64_t hash=14695981039346656037ull;juce::FileInputStream input(file);std::array<char,4096> bytes{};for(int n;(n=input.read(bytes.data(),int(bytes.size())))>0;)for(int i=0;i<n;++i){hash^=uint8_t(bytes[size_t(i)]);hash*=1099511628211ull;}auto path="samples/"+juce::String::toHexString(juce::int64(hash))+file.getFileExtension();zip.addFile(file,6,path);auto parameters=std::make_unique<juce::DynamicObject>();parameters->setProperty("tone",0);parameters->setProperty("color",1);parameters->setProperty("effect",0);parameters->setProperty("attack",.005);parameters->setProperty("release",.15);float root=60;auto words=juce::StringArray::fromTokens(file.getFileNameWithoutExtension()," ","");for(const auto& word:words)if(word.length()==2&&word[1]>='0'&&word[1]<='8'){const int semitone=juce::String("C D EF G A B").indexOfChar(word[0]);if(semitone>=0)root=float((int(word[1]-'0')+1)*12+semitone);}parameters->setProperty("sampleRoot",root);auto preset=std::make_unique<juce::DynamicObject>();preset->setProperty("name",file.getFileNameWithoutExtension());preset->setProperty("sample",path);preset->setProperty("source",file.getFileName());preset->setProperty("parameters",juce::var(parameters.release()));presets.add(juce::var(preset.release()));}
    auto bank=std::make_unique<juce::DynamicObject>();bank->setProperty("formatVersion",1);bank->setProperty("name","My samples");bank->setProperty("presets",presets);auto json=juce::JSON::toString(juce::var(bank.release()));zip.addEntry(new juce::MemoryInputStream(json.toRawUTF8(),json.getNumBytesAsUTF8(),true),6,"bank.json",juce::Time::getCurrentTime());auto temp=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("pocket-samples",".zip",false);{juce::FileOutputStream stream(temp);if(!zip.writeToStream(stream,nullptr)){error="Could not prepare the sample bank.";return false;}}const bool ok=importUserBank(temp,error);temp.deleteFile();return ok;
}

bool PocketProcessor::copySound(juce::String& error){if(state.getRawParameterValue("tapePlay")->load()>.5f){error="Stop tape before copying a sound.";return false;}juce::MemoryBlock data;getStateInformation(data);auto xml=getXmlFromBinary(data.getData(),int(data.getSize()));if(!xml){error="Could not copy this sound.";return false;}auto tree=juce::ValueTree::fromXml(*xml);tree.removeProperty("tapeAudio",nullptr);tree.removeChild(tree.getChildWithName("TapeEdits"),nullptr);tree.removeChild(tree.getChildWithName("SoundLibrary"),nullptr);for(int i=tree.getNumChildren();--i>=0;){const auto child=tree.getChild(i);const auto id=child.getProperty("id").toString();if(!child.hasType("PARAM")||id.startsWith("tape")||id.startsWith("track")||id.startsWith("master")||id.startsWith("eq")||id.startsWith("input")||id=="tempo"||id=="volume"||id.startsWith("seq")||id.startsWith("arp")||id=="metronome"||id=="clickVolume")tree.removeChild(i,nullptr);}soundClipboard=tree;soundClipboardId=selectedSound();clipboardKind.store(2);return true;}
bool PocketProcessor::pasteSound(juce::String& error){if(!soundClipboard.isValid()){error="Lift a sound in synth/drum mode first.";return false;}if(state.getRawParameterValue("tapePlay")->load()>.5f){error="Stop tape before pasting a sound.";return false;}juce::MemoryBlock data;getStateInformation(data);auto xml=getXmlFromBinary(data.getData(),int(data.getSize()));if(!xml)return false;auto merged=juce::ValueTree::fromXml(*xml);for(const auto& child:soundClipboard){auto target=merged.getChildWithProperty("id",child.getProperty("id"));if(target.isValid())target.setProperty("value",child.getProperty("value"),nullptr);}for(int i=-1;i<8;++i){const juce::Identifier key(i<0?juce::String("sampleAudio"):"kitAudio"+juce::String(i));if(soundClipboard.hasProperty(key))merged.setProperty(key,soundClipboard.getProperty(key),nullptr);else merged.removeProperty(key,nullptr);}merged.setProperty("factoryPreset",soundClipboard.getProperty("factoryPreset",-1),nullptr);merged.getChildWithName("SoundLibrary").setProperty("selected",soundClipboardId,nullptr);if(auto output=merged.createXml()){copyXmlToBinary(*output,data);setStateInformation(data.getData(),int(data.getSize()));return true;}error="Could not restore the copied sound.";return false;}
